private void setStatus(TEST_RunTestDataPreparationStatus _status)
{
    switch (_status)
    {
        case TEST_RunTestDataPreparationStatus::New:
            StatusOutput.text('New');
            break;
        case TEST_RunTestDataPreparationStatus::Error:
            StatusOutput.text('Error');
            break;
        case TEST_RunTestDataPreparationStatus::Succeeded:
            StatusOutput.text('Succeeded');
            break;
    }
}

private void appendLog(str _message)
{
    str logText = LogMessageOutput.text();

    if (!_message)
    {
        return;
    }

    if (logText)
    {
        logText += '; ';
    }

    logText += _message;
    LogMessageOutput.text(logText);
}

private void appendInfologToLogMessage()
{
    SysInfologEnumerator    enumerator = SysInfologEnumerator::newData(infolog.cut());
    SysInfologMessageStruct messageStruct;

    while (enumerator.moveNext())
    {
        messageStruct = new SysInfologMessageStruct(enumerator.currentMessage());

        if (messageStruct)
        {
            element.appendLog(messageStruct.message());
        }
    }
}

/// <summary>
/// Runs one MD12 seeding job. Each job purges its own FileName first, so
/// pressing the same button twice is safe.
/// Seeding only - batch execution and journal verification are done by hand.
/// </summary>
private void runSeedingJob(int _jobNumber)
{
    SJPMDInventCountingWarehouseId warehouseA = WarehouseAInput.text();
    SJPMDInventCountingWarehouseId warehouseB = WarehouseBInput.text();
    str                            result;

    element.setStatus(TEST_RunTestDataPreparationStatus::New);
    LogMessageOutput.text('');

    infolog.clear();

    try
    {
        switch (_jobNumber)
        {
            case 1:
                result = TEST_MD12SeedingJob01::seed(warehouseA, warehouseB);
                break;
            case 2:
                result = TEST_MD12SeedingJob02::seed(warehouseA, warehouseB);
                break;
            case 3:
                result = TEST_MD12SeedingJob03::seed(warehouseA, warehouseB);
                break;
            case 4:
                result = TEST_MD12SeedingJob04::seed(warehouseA, warehouseB);
                break;
            case 5:
                result = TEST_MD12SeedingJob05::seed(warehouseA, warehouseB);
                break;
            case 6:
                result = TEST_MD12SeedingJob06::seed(warehouseA, warehouseB);
                break;
            case 7:
                result = TEST_MD12SeedingJob07::seed(warehouseA, warehouseB);
                break;
            case 8:
                result = TEST_MD12SeedingJob08::seed(warehouseA, warehouseB);
                break;
            case 9:
                result = TEST_MD12SeedingJob09::seed(warehouseA, warehouseB);
                break;
            case 10:
                result = TEST_MD12SeedingJob10::seed(warehouseA, warehouseB);
                break;
            case 11:
                result = TEST_MD12VolumeSeedJob::seed();
                break;
            case 12:
                result = TEST_MD12VolumeVerifyJob::verify();
                break;
            default:
                throw error(strFmt('TEST_MD12: unknown seeding job %1.', _jobNumber));
        }

        element.appendLog(result);

        // The verify job returns FAIL | ... instead of throwing.
        element.setStatus(subStr(result, 1, 4) == 'FAIL'
            ? TEST_RunTestDataPreparationStatus::Error
            : TEST_RunTestDataPreparationStatus::Succeeded);
    }
    catch (Exception::CLRError)
    {
        error('TEST_MD12: CLR error while seeding.');
        element.setStatus(TEST_RunTestDataPreparationStatus::Error);
    }
    catch (Exception::Error)
    {
        element.setStatus(TEST_RunTestDataPreparationStatus::Error);
    }

    element.appendInfologToLogMessage();
}
